import{_ as r,a0 as i,w as a,s as m,ao as p,I as s,a1 as n,A as l,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"怎樣把壞的MySQL查詢找到並殺死？ | LCTT x X-CMD","titleTemplate":false,"description":"怎樣把壞的MySQL查詢找到並殺死？ | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎樣把壞的MySQL查詢找到並殺死？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎樣把壞的MySQL查詢找到並殺死？ | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140703 How to find and kill misbehaving MySQL queries","title":"怎樣把壞的MySQL查詢找到並殺死？","tag":"201407","desc":""},"relativePath":"201407/20140703 How to find and kill misbehaving MySQL queries.md","filePath":"[post].md"}'),d={name:"201407/20140703 How to find and kill misbehaving MySQL queries.md"};function L(u,e,y,f,S,h){const o=i("Link");return a(),m("div",null,[e[12]||(e[12]=p(`<h1 id="怎樣把壞的mysql查詢找到並殺死" tabindex="-1">怎樣把壞的MySQL查詢找到並殺死？ <a class="header-anchor" href="#怎樣把壞的mysql查詢找到並殺死" aria-label="Permalink to “怎樣把壞的MySQL查詢找到並殺死？”">​</a></h1><p>有時，關係型相關資料庫系統的複雜性會把你搞暈，不過幸運的是，使用MySQL工具來管理查詢就就可以避免這些複雜性。 在本教程中，我將向你們展示 <strong>怎樣去查找並殺掉任何非法的MySQL查詢</strong>。</p><p>為了瀏覽當前正在運行的查詢，登陸到MySQL終端，然後運行‘show processlist’命令:</p><pre><code>mysql&gt; show processlist; 

+--------+--------+-----------------+---------+---------+-------+-------+------------------+-----------+---------------+-----------+
| Id     | User   | Host            | db      | Command | Time  | State | Info             | Rows_sent | Rows_examined | Rows_read |
+--------+--------+-----------------+---------+---------+-------+-------+------------------+-----------+---------------+-----------+
|  78233 | root   | 127.0.0.1:37527 | mysql   | Sleep   | 16474 |       | NULL             |         6 |             6 |         6 |
|  84546 | root   | 127.0.0.1:48593 | mysql   | Sleep   | 13237 |       | NULL             |         2 |             2 |         2 |
| 107083 | root   | 127.0.0.1:56451 | mysql   | Sleep   | 15488 |       | NULL             |         1 |           121 |       121 |
| 131455 | root   | 127.0.0.1:48550 | NULL    | Query   |     0 | NULL  | show processlist |         0 |             0 |         0 |
+--------+--------+-----------------+---------+---------+-------+-------+------------------+-----------+---------------+-----------+
4 rows in set (0.03 sec)
</code></pre><p>首先你應該查看&#39;Time&#39;項，這裏記錄了進程執行 &quot;做其當做的事情&quot; 操作的秒數。‘command’項處於‘Sleep’ 狀態的進程表示其正在等待接受查詢，因此，它並沒有消耗任何資源。對於其他任何進程而言，‘Time’超過一定的秒數表明出現問題。</p><p>在上面的例子中，唯一運行的查詢是我們的‘show processlist’命令。讓我們來看看如果我們有一個寫的很爛的查詢是怎麼樣的:</p><pre><code>mysql&gt; show processlist; 

+--------+--------+-----------------+-----------+---------+-------+--------------+----------------------------------+-----------+---------------+-----------+
| Id     | User   | Host            | db        | Command | Time  | State        | Info                             | Rows_sent | Rows_examined | Rows_read |
+--------+--------+-----------------+-----------+---------+-------+--------------+----------------------------------+-----------+---------------+-----------+
|  78233 | root   | 127.0.0.1:37527 | example   | Sleep   | 18046 |              | NULL                             |         6 |             6 |         6 |
|  84546 | root   | 127.0.0.1:48593 | example   | Sleep   | 14809 |              | NULL                             |         2 |             2 |         2 |
| 107083 | root   | 127.0.0.1:56451 | example   | Sleep   | 17060 |              | NULL                             |         1 |           121 |       121 |
| 132033 | root   | 127.0.0.1:54642 | example   | Query   |    27 | Sending data | select max(subtotal) from orders |         0 |             0 |         0 |
| 133933 | root   | 127.0.0.1:48679 | NULL      | Query   |     0 | NULL         | show processlist                 |         0 |             0 |         0 |
| 134122 | root   | 127.0.0.1:49264 | example   | Sleep   |     0 |              | NULL                             |         0 |             0 |         0 |
+--------+--------+-----------------+-----------+---------+-------+--------------+----------------------------------+-----------+---------------+-----------+
6 rows in set (0.00 sec)
</code></pre><p>啊哈！現在我們看到有一個查詢運行了將近30秒。如果我們不想讓它的進程繼續運行，可以將它的&#39;Id&#39;傳遞給kill命令:</p><pre><code>mysql&gt; kill 132033;
Query OK, 0 rows affected (0.00 sec)
mysql&gt; 
</code></pre><p>(注意 由於我們沒有改變任何數據，MySQL總是報告0行被影響。)</p><p>明智的使用kill命令能夠清除積壓的查詢。然而，要記住的是，那不是一種永久的方法 - 如果這些查詢來自你的程序，你需要去重寫它們，或者將繼續看到相同的問題不斷出現。</p><h3 id="另請參閲" tabindex="-1">另請參閲 <a class="header-anchor" href="#另請參閲" aria-label="Permalink to “另請參閲”">​</a></h3><p>關於不同‘命令’的MySQL文檔:</p>`,13)),s("ul",null,[s("li",null,[n(o,{href:"https://dev.mysql.com/doc/refman/5.7/en/thread-commands.html"},{default:l(()=>[...e[0]||(e[0]=[t("https://dev.mysql.com/doc/refman/5.7/en/thread-commands.html",-1)])]),_:1})])]),e[13]||(e[13]=s("hr",null,null,-1)),s("p",null,[e[2]||(e[2]=t("via: ",-1)),n(o,{href:"http://xmodulo.com/2014/07/find-kill-misbehaving-mysql-queries.html"},{default:l(()=>[...e[1]||(e[1]=[t("http://xmodulo.com/2014/07/find-kill-misbehaving-mysql-queries.html",-1)])]),_:1})]),s("p",null,[e[5]||(e[5]=t("譯者：",-1)),n(o,{href:"https://github.com/hunanchenxingyu"},{default:l(()=>[...e[3]||(e[3]=[t("hunanchenxingyu",-1)])]),_:1}),e[6]||(e[6]=t(" 校對：",-1)),n(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[9]||(e[9]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[7]||(e[7]=[t("LCTT",-1)])]),_:1}),e[10]||(e[10]=t(" 原創翻譯，",-1)),n(o,{href:"http://linux.cn/"},{default:l(()=>[...e[8]||(e[8]=[t("Linux中國",-1)])]),_:1}),e[11]||(e[11]=t(" 榮譽推出",-1))])])}const w=r(d,[["render",L]]);export{g as __pageData,w as default};
